@AbapCatalog.sqlViewName: 'ZCDS_SIMPLE_SQL'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'cds Simple'
@ObjectModel.usageType:{
    serviceQuality: #X,
    sizeCategory: #S,
    dataClass: #MIXED
    }
define view ZCDS_SIMPLE_Demo1 
//with parameters p_vbtyp : vbtyp 
//,P_VKORG : vkorg
as select from vbak
{
     key vbeln as SaleDocNo,
  vbtyp,
  vkorg,
  vtweg,
  spart,
  kunnr,
 // netwr,
  
   case vbtyp
        when 'A' then 'Inquiry'
        when 'B' then 'Quotation'
        when 'C' then //'Order' 
            case netwr
                 when 0 then 'Order - Not Paid'
                else 'Order - Paid'
            end    
        else 'Others'
    end as DocCatText,    
  
    $session.client as ClientNum,
    $session.system_date as SystemDate,
    $session.system_language as SystemLanguage,
    $session.user as UserName,
    $session.user_date as UserDate,
    $session.user_timezone as UserTimeZone  
}
//where vbtyp = 'C'
//where vbtyp = $parameters.p_vbtyp
//and vkorg = $parameters.P_VKORG

@AbapCatalog.sqlViewName: 'ZMM_PO_DOC_SQL'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'PO DOC'
define view ZMM_PO_DOC as select from ekko
association [ 1..*] to ekpo as POI on POI.ebeln = ekko.ebeln
{
   key ebeln,
       bstyp,
       lifnr,
       POI 
}
where bstyp ='F'

@AbapCatalog.sqlViewName: 'ZSD_DATE_FUNC_V'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Date Func'
define view ZSD_DATE_FUNC 
as select from vbak 
    {
    key vbeln as Sales_Doc,
    
    erdat as Created_Date,
    
    // Current date
    cast( '20210901' as abap.dats) as Curr_Date,
    
    // YYYYMMDD
    //DATS_IS_VALID( cast( '20210901' as abap.dats) ) as Ret_code
    //DATS_IS_VALID( cast( '01192021' as abap.dats) ) as Ret_code
    
    // DDMMYYYY
    case DATS_IS_VALID( cast( '01092021' as abap.dats) )
        when 0 then 'Date is NOT Valid'
            when 1 then 'Date is Valid'
               else ''
    end as Ret_Text,
    
    // DATS_DAYS_BETWEEN
    DATS_DAYS_BETWEEN( 
        cast( '20210901' as abap.dats), // Order Date
        cast( '20210910' as abap.dats)  // Delivery Date
    ) as Days_Between,
    
     // DATS_ADD_DAYS  
     DATS_ADD_DAYS( 
         cast( '20210901' as abap.dats), // Order Date
         15,  // Exp. Delivery 
         'INITIAL'
         
      ) as Delivery_Date,
      
    // DATS_ADD_MONTHS
    DATS_ADD_MONTHS( 
      cast( '20210901' as abap.dats), // Order Date
      1, //Add Month
      'INITIAL'
    ) as Return_Exp
      
           
    
        
    }
    where vbtyp = 'C'
    and   netwr <> 0

@AbapCatalog.sqlViewName: 'ZSD_DS_FUNC_V'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'Decimal Function'
define view ZSD_DS_FUNC as select from vbak 
    {
    key vbeln as Sales_Doc,
    netwr as Original_Val,
    
    // DECIMAL_SHIFT
    DECIMAL_SHIFT( 
        amount => netwr,
        currency => cast( '0 ' as abap.cuky(5) ) 
    ) as DS_0,
    
    DECIMAL_SHIFT( 
        amount => netwr,
        currency => cast( '1 ' as abap.cuky(5) ) 
    ) as DS_1,
    
    DECIMAL_SHIFT( 
        amount => netwr,
        currency => cast( '2 ' as abap.cuky(5) ) 
    ) as DS_2,
    
    DECIMAL_SHIFT( 
        amount => netwr,
        currency => cast( '3 ' as abap.cuky(5) ) 
    ) as DS_3,
    
    DECIMAL_SHIFT( 
        amount => netwr,
        currency => cast( '4 ' as abap.cuky(5) ) 
    ) as DS_4,
    
    DECIMAL_SHIFT( 
        amount => netwr,
        currency => cast( '5 ' as abap.cuky(5) ) 
    ) as DS_5
    
    
    
    
    
        
    }
    where vbtyp = 'C'
    and   waerk = 'INR'
    and   netwr <> 0

@AbapCatalog.sqlViewName: 'ZSD_DT_CONV_V'
@AbapCatalog.compiler.compareFilter: true
@AbapCatalog.preserveKey: true
@AccessControl.authorizationCheck: #NOT_REQUIRED
@EndUserText.label: 'SQL Date & Time Functions'
define view ZSD_DT_CONV as select from vbak
     {
     key vbeln as Sales_Doc,
     erdat as Created_Date, 
     erzet as Created_Time,
     
     // Current System time stamp
     TSTMP_CURRENT_UTCTIMESTAMP( ) as C_TStamp,
     
     // Split Date from Time stamp 
     TSTMP_TO_DATS( 
         TSTMP_CURRENT_UTCTIMESTAMP( ) , // Current time stamp
         ABAP_SYSTEM_TIMEZONE( $session.client, 'NULL' ), // Current system time zone
         $session.client,  // Current client
         'NULL' // Error
     ) as to_date,
     
     // Split Time from Time stamp
     TSTMP_TO_TIMS(
         TSTMP_CURRENT_UTCTIMESTAMP( ) , // Current time stamp
         ABAP_SYSTEM_TIMEZONE( $session.client, 'NULL' ), // Current system time zone
         $session.client,  // Current client
         'NULL' // Error
     ) as to_time,
     
     // Summer Time Indicator - 'X'
     TSTMP_TO_DST( 
         TSTMP_CURRENT_UTCTIMESTAMP( ) , // Current time stamp
         ABAP_SYSTEM_TIMEZONE( $session.client, 'NULL' ), // Current system time zone
         $session.client,  // Current client
         'NULL' // Error
     ) as Summer_Ind,
     
     
     // Generate time stamp based on Date & Time
     DATS_TIMS_TO_TSTMP(
         erdat, 
         erzet, 
         ABAP_SYSTEM_TIMEZONE( $session.client, 'NULL' ), // Current system time zone
         $session.client,
         'NULL' // Error
     ) as N_TStamp
      
        
    }
    where vbtyp = 'C'
